use std::sync::Mutex;

static INNER: Mutex<i32> = Mutex::new(1);

pub struct StaticAliasRef {
    pub value: i32,
    pub is_static: bool,
}

pub fn static_alias(outer: i32) -> StaticAliasRef {
    let mut inner = INNER.lock().unwrap();
    if outer >= *inner {
        *inner = inner.wrapping_add(outer);
        StaticAliasRef {
            value: *inner,
            is_static: true,
        }
    } else {
        let new_outer = outer.wrapping_add(*inner);
        StaticAliasRef {
            value: new_outer,
            is_static: false,
        }
    }
}

pub fn driver(initial_value: i32, iterations: i32) {
    let mut running_sum = initial_value;
    let mut is_pointing_to_static = false;

    for _ in 0..iterations {
        let result = static_alias(running_sum);
        is_pointing_to_static = result.is_static;
        running_sum = result.value;
        output_i32(running_sum);
        crate::ffi::put_byte(b'\n');
    }
}

fn output_i32(val: i32) {
    if val < 0 {
        crate::ffi::put_byte(b'-');
        output_u32((val.wrapping_neg()) as u32);
    } else {
        output_u32(val as u32);
    }
}

fn output_u32(mut val: u32) {
    if val == 0 {
        crate::ffi::put_byte(b'0');
        return;
    }

    let mut digits = [0u8; 10];
    let mut count = 0;
    while val > 0 {
        digits[count] = (val % 10) as u8 + b'0';
        val /= 10;
        count += 1;
    }

    for i in (0..count).rev() {
        crate::ffi::put_byte(digits[i]);
    }
}
